-- ----------------------------
-- Table structure for t_notice
-- ----------------------------
DROP TABLE IF EXISTS `t_notice`;
CREATE TABLE `t_notice`  (
  `ID` varchar(36) NOT NULL COMMENT '主键ID UUID',
  `STATUS` char(1) DEFAULT NULL COMMENT '状态 正常/删除/审核/锁定 0/1/2/3',
  `VERSION` int(11) DEFAULT NULL COMMENT '版本号',
  `CREATE_USER` varchar(36) DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime(0) DEFAULT NULL COMMENT '创建时间',
  `UPDATE_USER` varchar(36) DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime(0) DEFAULT NULL COMMENT '更新时间',
  `TITLE` varchar(512) DEFAULT NULL COMMENT '标题',
  `HEAD_IMAGE` varchar(36) DEFAULT NULL COMMENT '标题图',
  `TYPE` varchar(64) DEFAULT NULL COMMENT '类型 来源于数据字典 NOTICE_TYPE',
  `CONTENT` longtext COMMENT '内容',
  `USER_ID` varchar(36) DEFAULT NULL COMMENT '发布人',
  `ORGAN_ID` varchar(36) DEFAULT NULL COMMENT '发布部门',
  `IS_TOP` char(1) DEFAULT NULL COMMENT '是否置顶 是/否 1/0',
  `END_TOP_DAY` int(11) DEFAULT NULL COMMENT '结束置顶天数',
  `BIZ_MODE` char(1) DEFAULT NULL COMMENT '发布状态 未发布/已发布/已失效 0/1/2',
  `PUBLISH_TIME` datetime(0) DEFAULT NULL COMMENT '发布时间',
  `EFFECT_TIME` datetime(0) DEFAULT NULL COMMENT '生效时间',
  `INVALID_TIME` datetime(0) DEFAULT NULL COMMENT '失效时间',
  `IS_RECORD_READ` char(1) DEFAULT NULL COMMENT '是否记录查看情况 是/否 1/0',
  `RECEIVE_SCOPE` varchar(36) DEFAULT NULL COMMENT '接收范围 所在单位及以下/所在单位/所在部门及以下/所在部门/所有/自定义 2/3/4/5/10/0',
  `APP_ID` varchar(64) DEFAULT NULL COMMENT '应用标识',
  `TIP_MESSAGE` varchar(64) DEFAULT NULL COMMENT '提醒通道 多个之间以“,”分割 系统提醒：Message 微信：Weixin 短信 SMS 企业微信提醒：QYWeixin APP提醒：APP',
  `is_reply` char(1) DEFAULT NULL COMMENT '是否需要回复 是：1 否：0',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `PUBLISH_TIME`(`PUBLISH_TIME`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COMMENT = '通知' ROW_FORMAT = DYNAMIC;

