-- ----------------------------
-- Table structure for t_notice_message
-- ----------------------------
DROP TABLE IF EXISTS `t_notice_message`;
CREATE TABLE `t_notice_message`  (
  `ID` varchar(36) NOT NULL COMMENT '主键ID UUID',
  `STATUS` char(1) DEFAULT NULL COMMENT '状态 正常/删除/审核/锁定 0/1/2/3',
  `VERSION` int(11) DEFAULT NULL COMMENT '版本号',
  `CREATE_USER` varchar(36) DEFAULT NULL COMMENT '创建者',
  `CREATE_TIME` datetime(0) NOT NULL COMMENT '创建时间',
  `UPDATE_USER` varchar(36) DEFAULT NULL COMMENT '更新者',
  `UPDATE_TIME` datetime(0) DEFAULT NULL COMMENT '更新时间',
  `TITLE` varchar(512) DEFAULT NULL COMMENT '标题',
  `HEAD_IMAGE` varchar(36) DEFAULT NULL COMMENT '标题图',
  `CONTENT` text COMMENT '内容',
  `CATEGORY` varchar(36) DEFAULT NULL COMMENT '消息类型 ',
  `MSG_TYPE` varchar(36) DEFAULT NULL COMMENT '消息类型 文本：text；文本卡片：textcard ',
  `URL` varchar(512) DEFAULT NULL COMMENT '链接地址',
  `IMAGE` varchar(512) DEFAULT NULL COMMENT '图片',
  `SEND_TIME` datetime(0) DEFAULT NULL COMMENT '发送时间',
  `SENDER` varchar(36) DEFAULT NULL COMMENT '发送者',
  `ORGAN_ID` varchar(36) DEFAULT NULL COMMENT '发布部门',
  `BIZ_MODE` varchar(36) DEFAULT NULL COMMENT '状态（业务） 草稿:00 正在发布:02 已发布:01',
  `TIP_MESSAGE` varchar(36) DEFAULT NULL COMMENT '提醒通道 多个之间以“,”分割 系统提醒：Message 微信：Weixin 短信 SMS 企业微信提醒：QYWeixin APP提醒：APP',
  `APP_ID` varchar(64) DEFAULT NULL COMMENT '应用标识',
  PRIMARY KEY (`ID`, `CREATE_TIME`) USING BTREE,
  INDEX `STATUS`(`SENDER`) USING BTREE,
  INDEX `APP_ID`(`APP_ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COMMENT = '消息' ROW_FORMAT = DYNAMIC;

