-- ----------------------------
-- Table structure for t_sys_area
-- ----------------------------
DROP TABLE IF EXISTS `t_sys_area`;
CREATE TABLE `t_sys_area`  (
  `id` varchar(36) COMMENT '主键ID',
  `status` char(1) COMMENT '状态 正常/删除/审核/锁定 0/1/2/3',
  `version` int(11) COMMENT '版本号',
  `create_user` varchar(36) COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_user` varchar(36) COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `name` varchar(255) COMMENT '名称',
  `short_name` varchar(255) COMMENT '简称',
  `code` varchar(36) COMMENT '编码',
  `biz_code` varchar(64) COMMENT '信息分类编码',
  `type` varchar(36) COMMENT '类型 区域类型（1：国家；2：省（自治区、直辖市)；3：地市级(地区、自治州)；4：县级市(县、市辖区) 5：镇(乡、街道) ）6：村(社区) 9：其它',
  `sort` int(11) NULL DEFAULT NULL COMMENT '排序',
  `parent_id` varchar(36) COMMENT '父级ID',
  `parent_ids` varchar(512) COMMENT '上级ID集合',
  `remark` varchar(255) COMMENT '备注',
  `extend_attr` text COMMENT '自定义扩展数据 {\'key1\':Object,\'key2\':Object}',
