  `EMAIL` varchar(64)  COMMENT '邮箱地址',
  `PERSON_EMAIL` varchar(64)  COMMENT '个人邮箱',
  `MOBILE` varchar(36)  COMMENT '手机号',
  `TEL` varchar(36)  COMMENT '办公电话',
  `QQ` varchar(36)  COMMENT 'QQ',
  `ADDRESS` varchar(255)  COMMENT '住址',
  `DEFAULT_ORGAN_ID` varchar(36)  COMMENT '默认组织机构ID',
  `USER_TYPE` varchar(36)  COMMENT '用户类型 ',
  `REMARK` varchar(255)  COMMENT '备注',
  `SORT` int(11)  COMMENT '排序号',
  `WEIXIN` varchar(64)  COMMENT '微信',
  `position` varchar(128)  COMMENT '职务',
  `biz_code` varchar(64)  COMMENT '信息分类编码',
  `extend_attr` text  COMMENT '自定义扩展数据 {\'key1\':Object,\'key2\':Object}',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `LOGIN_NAME`(`LOGIN_NAME`) USING BTREE,
  INDEX `DEFAULE_ORGAN_ID`(`DEFAULT_ORGAN_ID`) USING BTREE
) ENGINE = InnoDB COMMENT = '用户表';

