-- ----------------------------
-- Function structure for getOrganHomeCompanyCode
-- ----------------------------
DROP FUNCTION IF EXISTS `getOrganHomeCompanyCode`;
delimiter ;;
CREATE FUNCTION `getOrganHomeCompanyCode`(rootId varchar(36)) RETURNS varchar(36) CHARSET utf8mb4
    COMMENT '查找所属单位（地市）机构编码'
BEGIN
DECLARE pId varchar(36) default '';
DECLARE str varchar(36) default rootId;
DECLARE pType varchar(36) default '';
DECLARE pCode varchar(64) default '';
DECLARE ppCode varchar(64) default '';
DECLARE code varchar(36) default '';
DECLARE type varchar(36) default '';

WHILE rootId IS NOT NULL DO
	SET code =(SELECT t.code FROM t_sys_organ t WHERE t.id = rootId);
	SET type =(SELECT t.type FROM t_sys_organ t WHERE t.id = rootId);
	SET pId =(SELECT t.parent_id FROM t_sys_organ t WHERE t.id = rootId);
	SET pType =(SELECT t.type FROM t_sys_organ t WHERE t.id = pId);

	SET pCode =(SELECT t.code FROM t_sys_organ t WHERE t.id = pId);
	SET ppCode =(SELECT p.code FROM t_sys_organ t LEFT JOIN t_sys_organ p ON t.parent_id = p.id WHERE t.id = pId);

	IF (pType = '0' AND ppCode = '11360001') THEN
		SET str = pCode;
		SET rootId = null;
	ELSEIF ((pType = '0' AND type = '0') OR pId IS NULL OR pId = '0') THEN
		SET str = code;
		SET rootId = null;
	ELSE
		SET rootId = pId;
	END IF;

END WHILE;
RETURN str;
END
;;
delimiter ;

